import "C"

import (
	"unsafe"
)

const SimdSize = 4

func p(s []float32) *C.float {
	if len(s) == 0 {
		return nil
	}
	if uintptr(unsafe.Pointer(&s[0]))%16 != 0 {
		panic(`cref: unaligned slice`)
	}
	return (*C.float)(unsafe.Pointer(&s[0]))
}

// pf is p for scalar float arrays, which need no alignment.
func pf(s []float32) *C.float {
	if len(s) == 0 {
		return nil
	}
	return (*C.float)(unsafe.Pointer(&s[0]))
}

// end returns a pointer one past the last element of s.
func end(s []float32) *C.float {
	return (*C.float)(unsafe.Add(unsafe.Pointer(unsafe.SliceData(s)), 4*len(s)))
}

func cint(b bool) C.int {
	if b {
		return 1
	}
	return 0
}

func Vadd(a, b, out []float32)          { C.c_vadd(p(a), p(b), p(out)) }
func Vsub(a, b, out []float32)          { C.c_vsub(p(a), p(b), p(out)) }
func Vmul(a, b, out []float32)          { C.c_vmul(p(a), p(b), p(out)) }
func Vmadd(a, b, c, out []float32)      { C.c_vmadd(p(a), p(b), p(c), p(out)) }
func Svmul(f float32, v, out []float32) { C.c_svmul(C.float(f), p(v), p(out)) }
func LdPs1(f float32, out []float32)    { C.c_ld_ps1(C.float(f), p(out)) }
func Interleave2(in1, in2, out1, out2 []float32) {
	C.c_interleave2(p(in1), p(in2), p(out1), p(out2))
}
func Uninterleave2(in1, in2, out1, out2 []float32) {
	C.c_uninterleave2(p(in1), p(in2), p(out1), p(out2))
}

// Vtranspose4 transposes the 4x4 matrix x in place.
func Vtranspose4(x []float32)           { C.c_vtranspose4(p(x)) }
func Vswaphl(a, b, out []float32)       { C.c_vswaphl(p(a), p(b), p(out)) }
func Vcplxmul(ar, ai, br, bi []float32) { C.c_vcplxmul(p(ar), p(ai), p(br), p(bi)) }
func Vcplxmulconj(ar, ai, br, bi []float32) {
	C.c_vcplxmulconj(p(ar), p(ai), p(br), p(bi))
}

func Passf2(ido, l1 int, cc, ch, wa1 []float32, fsign float32) {
	C.c_passf2(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), C.float(fsign))
}
func Passf3(ido, l1 int, cc, ch, wa1, wa2 []float32, fsign float32) {
	C.c_passf3(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), C.float(fsign))
}
func Passf4(ido, l1 int, cc, ch, wa1, wa2, wa3 []float32, fsign float32) {
	C.c_passf4(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3), C.float(fsign))
}
func Passf5(ido, l1 int, cc, ch, wa1, wa2, wa3, wa4 []float32, fsign float32) {
	C.c_passf5(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3), pf(wa4), C.float(fsign))
}

func Radf2(ido, l1 int, cc, ch, wa1 []float32) {
	C.c_radf2(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1))
}
func Radb2(ido, l1 int, cc, ch, wa1 []float32) {
	C.c_radb2(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1))
}
func Radf3(ido, l1 int, cc, ch, wa1, wa2 []float32) {
	C.c_radf3(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2))
}
func Radb3(ido, l1 int, cc, ch, wa1, wa2 []float32) {
	C.c_radb3(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2))
}
func Radf4(ido, l1 int, cc, ch, wa1, wa2, wa3 []float32) {
	C.c_radf4(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3))
}
func Radb4(ido, l1 int, cc, ch, wa1, wa2, wa3 []float32) {
	C.c_radb4(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3))
}
func Radf5(ido, l1 int, cc, ch, wa1, wa2, wa3, wa4 []float32) {
	C.c_radf5(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3), pf(wa4))
}
func Radb5(ido, l1 int, cc, ch, wa1, wa2, wa3, wa4 []float32) {
	C.c_radb5(C.int(ido), C.int(l1), p(cc), p(ch), pf(wa1), pf(wa2), pf(wa3), pf(wa4))
}

func cifac(ifac []int) []C.int {
	r := make([]C.int, len(ifac))
	for i, v := range ifac {
		r[i] = C.int(v)
	}
	return r
}

func goifac(cifac []C.int, ifac []int) {
	for i, v := range cifac {
		ifac[i] = int(v)
	}
}

// Rfftf1 returns 0 if the result ended up in work1, 1 if in work2 and -1 otherwise.
func Rfftf1(n int, in, work1, work2, wa []float32, ifac []int) int {
	ci := cifac(ifac)
	return int(C.c_rfftf1(C.int(n), p(in), p(work1), p(work2), pf(wa), &ci[0]))
}

// Rfftb1 returns 0 if the result ended up in work1, 1 if in work2 and -1 otherwise.
func Rfftb1(n int, in, work1, work2, wa []float32, ifac []int) int {
	ci := cifac(ifac)
	return int(C.c_rfftb1(C.int(n), p(in), p(work1), p(work2), pf(wa), &ci[0]))
}

// Cfftf1 returns 0 if the result ended up in work1, 1 if in work2 and -1 otherwise.
func Cfftf1(n int, in, work1, work2, wa []float32, ifac []int, isign int) int {
	ci := cifac(ifac)
	return int(C.c_cfftf1(C.int(n), p(in), p(work1), p(work2), pf(wa), &ci[0], C.int(isign)))
}

var IfacMaxSize = int(C.ifac_max_size())

func Decompose(n int, ifac, ntryh []int) int {
	ci := cifac(ifac)
	cn := cifac(ntryh)
	nf := int(C.c_decompose(C.int(n), &ci[0], &cn[0]))
	goifac(ci, ifac)
	return nf
}

func Rffti1(n int, wa []float32, ifac []int) {
	ci := cifac(ifac)
	C.c_rffti1(C.int(n), (*C.float)(unsafe.Pointer(&wa[0])), &ci[0])
	goifac(ci, ifac)
}

func Cffti1(n int, wa []float32, ifac []int) {
	ci := cifac(ifac)
	C.c_cffti1(C.int(n), (*C.float)(unsafe.Pointer(&wa[0])), &ci[0])
	goifac(ci, ifac)
}

type Setup struct {
	s *C.PFFFT_Setup
}

// NewSetup returns nil if n is not supported. Setups are never freed.
func NewSetup(n int, real bool) *Setup {
	t := C.pffft_transform_t(C.PFFFT_COMPLEX)
	if real {
		t = C.PFFFT_REAL
	}
	s := C.cref_pffft_new_setup(C.int(n), t)
	if s == nil {
		return nil
	}
	return &Setup{s}
}

func (s *Setup) N() int     { return int(C.setup_n(s.s)) }
func (s *Setup) Ncvec() int { return int(C.setup_ncvec(s.s)) }

func (s *Setup) Ifac() []int {
	r := make([]int, IfacMaxSize)
	for i := range r {
		r[i] = int(C.setup_ifac(s.s, C.int(i)))
	}
	return r
}

// E returns the e coefficients, 2*Ncvec*(SimdSize-1)/SimdSize vectors.
func (s *Setup) E() []float32 {
	return unsafe.Slice((*float32)(unsafe.Pointer(C.setup_e(s.s))), 2*s.Ncvec()*(SimdSize-1))
}

// Twiddle returns the fftpack twiddle factors, the rest of the setup's data.
func (s *Setup) Twiddle() []float32 {
	return unsafe.Slice((*float32)(unsafe.Pointer(C.setup_twiddle(s.s))), 2*s.Ncvec())
}

// ReversedCopy writes backwards, starting from the end of out.
func ReversedCopy(n int, in []float32, inStride int, out []float32) {
	C.c_reversed_copy(C.int(n), p(in), C.int(inStride), end(out))
}

// UnreversedCopy writes to out starting at the vector with index outOff, moving by
// outStride vectors on every step.
func UnreversedCopy(n int, in []float32, out []float32, outOff, outStride int) {
	C.c_unreversed_copy(C.int(n), p(in), p(out[4*outOff:]), C.int(outStride))
}

func Zreorder(s *Setup, in, out []float32, forward bool) {
	C.cref_pffft_zreorder(s.s, p(in), p(out), dir(forward))
}

func CplxFinalize(ncvec int, in, out, e []float32) {
	C.c_cplx_finalize(C.int(ncvec), p(in), p(out), p(e))
}
func CplxPreprocess(ncvec int, in, out, e []float32) {
	C.c_cplx_preprocess(C.int(ncvec), p(in), p(out), p(e))
}
func RealFinalize4x4(in0, in1, in, e, out []float32) {
	C.c_real_finalize_4x4(p(in0), p(in1), p(in), p(e), p(out))
}
func RealFinalize(ncvec int, in, out, e []float32) {
	C.c_real_finalize(C.int(ncvec), p(in), p(out), p(e))
}
func RealPreprocess4x4(in, e, out []float32, first bool) {
	C.c_real_preprocess_4x4(p(in), p(e), p(out), cint(first))
}
func RealPreprocess(ncvec int, in, out, e []float32) {
	C.c_real_preprocess(C.int(ncvec), p(in), p(out), p(e))
}

func TransformInternal(s *Setup, in, out, scratch []float32, forward, ordered bool) {
	C.c_transform_internal(s.s, p(in), p(out), p(scratch), cint(forward), cint(ordered))
}

func dir(forward bool) C.pffft_direction_t {
	if forward {
		return C.PFFFT_FORWARD
	}
	return C.PFFFT_BACKWARD
}

func Transform(s *Setup, in, out, work []float32, forward bool) {
	C.cref_pffft_transform(s.s, p(in), p(out), p(work), dir(forward))
}

func TransformOrdered(s *Setup, in, out, work []float32, forward bool) {
	C.cref_pffft_transform_ordered(s.s, p(in), p(out), p(work), dir(forward))
}
